package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.BasketTemplate; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*;
public interface BasketTemplateRepository extends JpaRepository<BasketTemplate,Long>{ @EntityGraph(attributePaths={"products","products.product","materials","materials.material"}) @Query("select b from BasketTemplate b order by b.name") List<BasketTemplate> findAllDetailed(); @EntityGraph(attributePaths={"products","products.product","materials","materials.material"}) @Query("select b from BasketTemplate b where b.id=:id") Optional<BasketTemplate> findDetailed(@Param("id") Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select b from BasketTemplate b where b.id=:id") Optional<BasketTemplate> lockById(@Param("id") Long id); }
